using System;
namespace LoopPedal {
static class FxTypeChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static double[] Tail(int mode,float size){var f=new MasterFx{Reverb=1,ReverbMode=mode,Size=size};float l,r;for(int i=0;i<48000;i++)f.Process(0,0,out l,out r);double energy=0,late=0;int first=-1;for(int i=0;i<480000;i++){f.Process(i==0?.5f:0,i==0?.5f:0,out l,out r);Check(!float.IsNaN(l)&&!float.IsInfinity(l)&&Math.Abs(l)<2,"Reverb stable");double e=l*l+r*r;if(first<0&&e>1e-10)first=i;energy+=e;if(i>384000)late+=e;}return new[]{energy,late,(double)first};}
 static void Dc(){for(int mode=0;mode<2;mode++)foreach(float pos in new[]{0f,-.25f,-.6f,.4f}){var f=new MasterFx{ReverbMode=mode,Reverb=1,Size=1,Filter=pos};double sum=0,square=0;int clipped=0;for(int i=0;i<1440000;i++){float input=(float)(.08*Math.Sin(2*Math.PI*440*i/48000)+.05),l,r;f.Process(input,input,out l,out r);f.FilterOutput(input+l,input+r,out l,out r);Check(!float.IsNaN(l)&&!float.IsInfinity(l),"Hall DC finite");if(i>=1392000){sum+=l;square+=l*l;if(Math.Abs(l)>=1)clipped++;}}double mean=sum/48000;Check(clipped==0&&Math.Abs(mean-(pos>0?0:.05))<.003&&Math.Sqrt(Math.Max(0,square/48000-mean*mean))>.005,"Hall DC/LP/OFF output "+mode+" "+pos+" "+mean);}}
 static void Output(){var guard=new OutputGuard();float l,r;for(int i=0;i<48000;i++){float input=(float)(.8*Math.Sin(i*.071));guard.Process(input,input*.5f,out l,out r);Check(l==input&&r==input*.5f,"Output unity");}for(int i=0;i<96000;i++){float input=(float)(2.3*Math.Sin(i*.057));guard.Process(input,input*.5f,out l,out r);Check(Math.Abs(l)<1&&Math.Abs(r)<1&&Math.Abs(r-l*.5f)<1e-7,"Output ceiling/stereo link");}for(int i=0;i<240000;i++)guard.Process(0,0,out l,out r);guard.Process(.2f,-.1f,out l,out r);Check(l==.2f&&r==-.1f,"Output unity recovery");}
 public static void Run(){Output();Dc();var a=new MasterFx{Size=1};Check(Math.Abs(a.ReverbSeconds-18)<.001,"Extended Hall decay");var hall=Tail(0,.5f);var longHall=Tail(0,1);var room=Tail(1,.5f);Check(longHall[1]>hall[1]*4&&longHall[1]>1e-12&&room[2]<hall[2],"Hall long tail / Room distinction");
 for(int mode=0;mode<3;mode++){var f=new MasterFx{DelayMode=mode,Delay=1,DelaySync=false,Time=.04f,Feedback=.6f};float l,r;for(int i=0;i<48000;i++)f.Process(0,0,out l,out r);double l1=0,r1=0,l2=0,r2=0,energy=0,stereo=0;for(int i=0;i<192000;i++){float input=mode==2&&i<24000?(float)(.15*Math.Sin(i*.077)):mode!=2&&i==0?.3f:0;f.Process(input,input,out l,out r);Check(!float.IsNaN(l)&&!float.IsInfinity(l)&&Math.Abs(l)<3,"Delay stable "+mode);if(i>=1800&&i<2200){l1+=l*l;r1+=r*r;}if(i>=3700&&i<4100){l2+=l*l;r2+=r*r;}energy+=l*l+r*r;if(i>48000)stereo+=Math.Abs(l-r);}if(mode==0)Check(Math.Abs(l1-r1)<1e-7,"Standard stereo delay");if(mode==1)Check(l1>r1*100&&r2>l2*100,"Ping-Pong alternation");if(mode==2)Check(energy>.001&&stereo<.001,"POTS mono echo");if(mode==2){f.Feedback=.85f;for(int i=0;i<384000;i++){float input=i<96000?(float)(.2*Math.Sin(i*.097)):0;f.Process(input,input,out l,out r);Check(!float.IsNaN(l)&&!float.IsInfinity(l)&&Math.Abs(l)<3,"POTS high feedback bounded");}}f.Clear();for(int i=0;i<10000;i++){f.Process(0,0,out l,out r);Check(l==0&&r==0,"Clear mode tail");}}
 a.ReverbMode=1;a.DelayMode=2;a.GrainMode=2;var copy=a.Copy();Check(copy.ReverbMode==1&&copy.DelayMode==2&&copy.GrainMode==2,"Copy types");a.ResetDefaults();Check(a.ReverbMode==0&&a.DelayMode==0&&a.GrainMode==0,"Reset types");
 }
}
}
